Here's the plan. I've only read files so far and haven't changed anything. The Weft inbox is empty.

**What I found**
- `src/auth/session.ts` exports `createSession(userId)`, `getSession(token)`, `revokeSession(token)` and `resetSessions()`. A `Session` is `{ token, userId, createdAt }`.
- `login` in `src/api/routes.ts` starts a session with just `createSession(user.id)`. Refresh will do the same thing with the old session's `userId`.
- `test/session.test.ts` uses `node:test` and `node:assert/strict`, and calls `resetSessions()` in `beforeEach`. The new test will follow that pattern.

**File 1: `src/auth/refresh.ts`**
```ts
import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/** Swap a live session for a fresh one for the same user; undefined if the token isn't live. */
export function refreshSession(token: string): Session | undefined {
  const session = getSession(token);
  if (!session) return undefined;
  revokeSession(token);
  return createSession(session.userId);
}
```

**File 2: `test/refresh.test.ts`**
```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions } from "../src/auth/session.ts";
import { refreshSession } from "../src/auth/refresh.ts";

beforeEach(() => resetSessions());

test("refreshSession revokes the old session and issues a new one for the same user", () => {
  const old = createSession("u_1");
  const fresh = refreshSession(old.token);
  assert.ok(fresh);
  assert.equal(fresh.userId, "u_1");
  assert.notEqual(fresh.token, old.token);
  assert.equal(getSession(old.token), undefined);
  assert.equal(getSession(fresh.token)?.userId, "u_1");
});

test("refreshSession returns undefined for an unknown or already-refreshed token", () => {
  assert.equal(refreshSession("nope"), undefined);
  const s = createSession("u_2");
  refreshSession(s.token);
  assert.equal(refreshSession(s.token), undefined);
});
```

